Method.Implementation:
	 try{
		do ##super()
		$$$TRACE("OnInit Connect to " _ ..ApplicationAddress)
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.mmi.CdrHirsUNum).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))
     	set status = ..CheckObject()
	}catch err{
		$$$LOGERROR("Exception while Creating Tuxedo Service: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    set status=$$$ERROR(" Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}

	quit status

	 #dim status as %Status
	 set status = $$$OK
	 $$$TRACE("Inside IHC.ITF.Operation.OpHirsuNum OnMessage method <"_pRequest.StringValue_">")	 


	 try {	
	 	if (..CheckObject() '= $$$OK) {
		 	$$$TRACE("**** Object does not exists ****")
		 	// Try to re intialize
		 	set result = ..OnInit()
			if (result '= $$$OK)
			{
				set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Cdr-HirsUNum", "GetMMI failed. MMI#: " _pRequest.StringValue_ " ; Reason: " _ result)						
				return status
			}
	 	}

		$$$TRACE("Object name: " _ ..objCdrTuxService.%ClassName(1))
		$$$TRACE("Request EMPI# : " _ pRequest.StringValue)

		set pstatus=##class(IHC.ITF.ITFCOMMON.Utility).GetItemSettingValue("Op-Cdr-HirsUNum","FacilityNcid",.configValue)  
        if ($$$ISOK(pstatus)){
           set ncid = configValue
        } 
		$$$TRACE("Request Facility NCID : " _ ncid)

		set result = ..objCdrTuxService.getMMINum(ncid,pRequest.StringValue)	
		$$$TRACE("Ihc MRN#: " _result)	
		set pResponse = ##class(Ens.StringResponse).%New()  
 		set pResponse.StringValue = result 
 		$$$TRACE("**** After GetMMi Call ****"_pResponse.StringValue)	


 		//$$$TRACE("Result: " _ ": " _ result)
 		$$$TRACE("Result: ["_result_"] Length:"_$L(result))


	 } catch err {	
		    Set status = ..ExceptionHandler(err, "OnMessage")
	 }	    

	 $$$TRACE("OnMessage status: " _ status)	
	 return status
